// Generated by Suite Builder from a crawl of the site. What a test expects, each failing in plain English.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
import { Find, matchesOf, shownIn, textOf } from './Find';
import { Http } from './Http';
import { byXPath, element, type Locator, type PageElement } from './PageElement';
import { SiteConfig } from './SiteConfig';
import { StepLog } from './StepLog';
import { WaitActions } from './WaitActions';

/**
 * The library of checks. Each logs its step ("Check that the submit button is shown"), retries for
 * up to the command timeout (10 s by default) until it comes true, and otherwise fails with a
 * sentence that says what was expected and what was there: "Expected the total text to say
 * "$10.00", but it said "$0.00"." Page checks (a page's verify() actions) are built from these.
 */
export const Checks = {
  /** It is shown. */
  isShown(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is shown`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      if (!$found.length) throw new Error(`Expected ${element.label} to be shown, but it was not${waited()}`);
    });
  },

  /** It is gone, or hidden. */
  isNotShown(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is not shown`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element);
      if ($found.length) throw new Error(`Expected ${element.label} not to be shown, but it still was${waited()}`);
    });
  },

  /** All of them are shown: one step, and the failure names the first one missing. */
  allShown(what: string, ...elements: PageElement[]): void {
    StepLog.step(`Check that the page shows ${what}`);
    for (const element of elements) {
      cy.document({ log: false }).should((doc) => {
        const $found = shownIn(doc, element, true);
        if (!$found.length) throw new Error(`Expected the page to show ${element.label}, but it did not${waited()}`);
      });
    }
  },

  /** It says exactly this (runs of spaces and line breaks count as one space). */
  hasText(element: PageElement, expected: string): void {
    StepLog.step(`Check that ${element.label} says "${expected}"`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      const text = $found.length ? textOf($found) : null;
      if (!WaitActions.sameText(text, expected)) throw new Error(`Expected ${element.label} to say "${expected}", but it said ${quoted(text)}${waited()}`);
    });
  },

  /** A field holds exactly this: what was typed into it. */
  hasValue(element: PageElement, expected: string): void {
    StepLog.step(`Check that ${element.label} holds "${expected}"`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      // A dropdown holds the option it shows, by its words, as choose() picks it (its value can differ).
      const list = $found[0] instanceof doc.defaultView!.HTMLSelectElement ? ($found[0] as HTMLSelectElement) : null;
      const value = !$found.length ? null : list ? (list.selectedOptions[0]?.text ?? '') : String($found.val() ?? '');
      if (value !== expected) throw new Error(`Expected ${element.label} to hold "${expected}", but it held ${quoted(value)}${waited()}`);
    });
  },

  /** Its text contains this. */
  containsText(element: PageElement, expected: string): void {
    StepLog.step(`Check that ${element.label} mentions "${expected}"`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      const text = $found.length ? textOf($found) : null;
      if (!WaitActions.containsText(text, expected)) throw new Error(`Expected ${element.label} to mention "${expected}", but it said ${quoted(text)}${waited()}`);
    });
  },

  /** The page shows this text somewhere a visitor can see it (any case; part of a longer text is fine). */
  pageShowsText(text: string): void {
    StepLog.step(`Check that the page shows "${text}"`);
    cy.document({ log: false }).should((doc) => {
      const shown = doc.body ? doc.body.innerText : '';
      if (!WaitActions.containsText(shown.toLowerCase(), text.toLowerCase())) throw new Error(`Expected the page to show "${text}", but it did not${waited()}`);
    });
  },

  /**
   * The page shows this many of them. It takes the locator of all of them, byCss('ul.results > li'),
   * as a page element stands for the first match. Hidden ones (a mobile menu's copies) are not counted.
   */
  hasCount(what: string, all: Locator, expected: number): void {
    StepLog.step(`Check that the page shows ${expected} ${what}`);
    cy.document({ log: false }).should((doc) => {
      const shown = matchesOf(doc, all).filter((e) => Cypress.dom.isVisible(e)).length;
      if (shown !== expected) throw new Error(`Expected the page to show ${expected} ${what}, but it showed ${shown}${waited()}`);
    });
  },

  /**
   * The page shows a link to each of these addresses, by its href as written: a list still leading to
   * every page it led to in the crawl. Fails naming each one gone.
   */
  linksToEach(what: string, hrefs: string[]): void {
    StepLog.step(`Check that the page links to each of its ${hrefs.length} ${what}`);
    cy.document({ log: false }).should((doc) => {
      const links = Array.from(doc.querySelectorAll<HTMLAnchorElement>('a[href]')).filter((a) => Cypress.dom.isVisible(a));
      const gone = hrefs.filter((href) => !links.some((a) => a.getAttribute('href') === href));
      if (gone.length) throw new Error(`Expected the page to link to each of its ${hrefs.length} ${what}, but ${gone.length} ${gone.length === 1 ? 'is' : 'are'} gone: ${gone.join(', ')}${waited()}`);
    });
  },

  /** Each value is its own: no two the same. allDifferent("page types' titles", names, titles) fails naming the two that share one. */
  allDifferent(what: string, names: string[], values: string[]): void {
    StepLog.step(`Check that each of the ${what} is its own`);
    const first = new Map<string, string>();
    const same: string[] = [];
    values.forEach((value, i) => {
      const earlier = first.get(value);
      if (earlier === undefined) first.set(value, names[i]);
      else same.push(`${earlier} and ${names[i]} both have "${value}"`);
    });
    if (same.length) throw new Error(`Expected each of the ${what} to be its own, but ${same.join('; ')}`);
  },

  /**
   * Clicks a control the crawl saw on most of the site's pages (a carousel's Next, a "More" toggle),
   * found by its XPath, and checks that the page around it changes: the region it is in, the control
   * itself (aria-expanded), or the page's own classes. Only controls that move or open something are
   * tested this way: nothing is sent (G-125).
   */
  clickChangesThePage(label: string, xpath: string): void {
    StepLog.step(`Click ${label} and check that the page changes around it`);
    let before: string | null = null;
    cy.document({ log: false }).then((doc) => {
      before = aroundIt(doc, xpath);
      if (before === null) throw new Error(`Expected the page to show ${label}, but it did not`);
    });
    Find.visible(element('CONTROL', byXPath(xpath), label)).click({ log: false });
    cy.document({ log: false }).should((doc) => {
      if (aroundIt(doc, xpath) === before) throw new Error(`Expected clicking ${label} to change the page around it (a slide, a panel, a menu), but nothing changed${waited()}`);
    });
  },

  /** It is shown, and can be used (a button or field that is not disabled). */
  isEnabled(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is enabled`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      if (!$found.length || $found.is(':disabled')) throw new Error(`Expected ${element.label} to be enabled, but it was ${$found.length ? 'disabled' : 'not shown'}${waited()}`);
    });
  },

  /** It is shown, and disabled. */
  isDisabled(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is disabled`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      if (!$found.length || !$found.is(':disabled')) throw new Error(`Expected ${element.label} to be disabled, but it was ${$found.length ? 'enabled' : 'not shown'}${waited()}`);
    });
  },

  /** A checkbox or radio button is shown, and ticked. */
  isChecked(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is checked`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      if (!$found.length || !$found.is(':checked')) throw new Error(`Expected ${element.label} to be checked, but it was ${$found.length ? 'not' : 'not shown'}${waited()}`);
    });
  },

  /** A checkbox or radio button is shown, and not ticked. */
  isNotChecked(element: PageElement): void {
    StepLog.step(`Check that ${element.label} is not checked`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      if (!$found.length || $found.is(':checked')) throw new Error(`Expected ${element.label} not to be checked, but it was ${$found.length ? 'checked' : 'not shown'}${waited()}`);
    });
  },

  /**
   * The browser will not send the field's form with the field as it is: it is required, empty, and
   * its form leaves the browser's own check on. Asked of the field, never by sending: nothing leaves
   * the browser (G-116).
   */
  refusesEmpty(element: PageElement): void {
    StepLog.step(`Check that the form is not sent with ${element.label} empty`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      const why = $found.length ? whyItWouldSend($found[0] as HTMLInputElement) : 'it was not shown';
      if (why) throw new Error(`Expected the form not to be sent with ${element.label} empty, but ${why}${waited()}`);
    });
  },

  /** Its attribute holds exactly this: hasAttribute(HELP_LINK, 'href', '/help'). */
  hasAttribute(element: PageElement, name: string, expected: string): void {
    StepLog.step(`Check that ${element.label}'s ${name} is "${expected}"`);
    cy.document({ log: false }).should((doc) => {
      const $found = shownIn(doc, element, true);
      const value = $found.length ? $found.attr(name) : undefined;
      if (value !== expected) {
        const was = !$found.length ? 'nothing (it was not shown)' : value === undefined ? 'missing' : `"${value}"`;
        throw new Error(`Expected ${element.label}'s ${name} to be "${expected}", but it was ${was}${waited()}`);
      }
    });
  },

  /** The browser is on this path of the site. */
  isOnPath(path: string): void {
    StepLog.step(`Check that the browser is on ${path}`);
    WaitActions.forUrl(path, (url) => `Expected to be on ${path}, but the browser was on ${url}${waited()}`);
  },

  /** The page's title is exactly this. */
  titleIs(title: string): void {
    StepLog.step(`Check that the page title is "${title}"`);
    WaitActions.forTitle(title, (actual) => `Expected the page title "${title}", but it was "${actual}"${waited()}`);
  },

  /**
   * What the test needs is there (the data it uses, a state of the site): when it is not, the test is
   * skipped, saying why, never failed. Name the data: `Checks.assume(policies.length > 0, 'no policy with
   * an amount due in policies.csv')`; inside a `.then()` for data Cypress reads. Not a check (SR-19): the
   * test still checks something.
   */
  assume(met: boolean, why: string): void {
    if (met) return;
    StepLog.step(`Skipped: ${why}`);
    cy.then(() => {
      const test = Cypress.currentTest;
      cy.task('testSkipped', { spec: Cypress.spec.name, title: test.titlePath.join(' > '), why }, { log: false });
    }).then(() => {
      // Mocha's skip, from inside a queued command: seen to work in a test body on Ghost's run, 2026-10-04 (Cypress 16.1.1).
      (cy as unknown as { state(name: 'runnable'): { ctx: Mocha.Context } }).state('runnable').ctx.skip();
    });
  },

  /** The address answers, and lands where it says (a redirect means the link points to an old or moved address). */
  answers(path: string): void {
    StepLog.step(`Check that ${path} answers`);
    Http.get(SiteConfig.url(path)).then((answer) => {
      if (!answer.ok) throw new Error(`${path} answered ${answer.status}`);
      if (!WaitActions.samePage(answer.url, SiteConfig.url(path))) throw new Error(`${path} redirects to ${answer.url} (the link points to an old or moved address)`);
    });
  },

  /**
   * The link report (G-118): every address the crawl requested (support/links.ts: its path, what it
   * answered then, pages linking to it), asked once more, the report in cypress/link-report.md. Fails
   * only on one that answered 2xx in the crawl and does not now; one already broken then is listed
   * as known, never failed again.
   */
  linksAnswerAsInTheCrawl(links: [string, number | null, string[]][]): void {
    StepLog.step(`Ask the ${links.length} addresses the crawl requested, once each (cypress/link-report.md)`);
    const rows: { broken: string[]; known: string[]; fine: string[]; since: string[] } = { broken: [], known: [], fine: [], since: [] };
    const ok = (status: number | null) => status !== null && status >= 200 && status < 300;
    const said = (status: number | null) => (status === null ? 'no answer' : String(status));
    for (const [path, then, from] of links) {
      Http.get(SiteConfig.url(path)).then((answer) => {
        const row = `| ${path} | ${said(then)} | ${said(answer.status)} | ${from.join(', ')} |`;
        if (ok(then) && !answer.ok) {
          rows.broken.push(row);
          rows.since.push(`${path} answered ${answer.status} (${then} in the crawl)`);
        } else (ok(then) ? rows.fine : rows.known).push(row);
      });
    }
    cy.then(() => {
      const section = (title: string, list: string[]) => `\n## ${title} (${list.length})\n\n${list.length ? `| Address | In the crawl | Now | Linked from |\n| --- | --- | --- | --- |\n${list.join('\n')}\n` : 'None.\n'}`;
      const md = `# Link report\n\nEvery address the crawl requested, asked again by this run. One that answered in the crawl\nand does not now fails the link report; one already broken in the crawl is listed as known.\n${section('Broken since the crawl', rows.broken)}${section('Broken in the crawl, still listed', rows.known)}${section('Answering as in the crawl', rows.fine)}`;
      return cy.writeFile('cypress/link-report.md', md, { log: false });
    }).then(() => {
      if (rows.since.length) throw new Error(`Broken since the crawl (cypress/link-report.md): ${rows.since.join('; ')}`);
    });
  },

  /** An address that cannot exist answers 404: the site says a missing page is missing (G-117). */
  isNotFound(path: string): void {
    StepLog.step(`Check that ${path} answers 404 (not found)`);
    Http.get(SiteConfig.url(path)).then((answer) => {
      if (answer.status !== 404) throw new Error(`${path} answered ${answer.status}, not 404: a page that does not exist should say so`);
    });
  },

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // More checks this site needs (a price format, a sorted list), each logging its step and
  // failing with a sentence that says what it expected.
  // ==== END YOURS (extras) ====
};

function quoted(text: string | null): string {
  return text === null ? 'nothing (it was not shown)' : `"${text.trim()}"`;
}

/** The script that reads the page around a control (the same in every framework Suite Builder writes). */
const AROUND_IT = '(function (xpath, doc) {\n  var d = doc || document;\n  var el = d.evaluate(xpath, d, null, 9, null).singleNodeValue;\n  if (!el) return null;\n  var parent = el.parentElement;\n  var box = (parent && parent.closest("section, nav, header, aside, footer, [role=region], [role=navigation], [aria-roledescription], [class*=carousel], [class*=slider], [class*=swiper], [class*=accordion], [class*=menu], [class*=dropdown]")) || parent || el;\n  return box.outerHTML + "\\u0000" + el.outerHTML + "\\u0000" + (d.body ? d.body.className : "");\n})';

/** The page around the control, as text to compare; null when the control is not there. */
function aroundIt(doc: Document, xpath: string): string | null {
  return (new Function(`return ${AROUND_IT}`)() as (xpath: string, doc: Document) => string | null)(xpath, doc);
}

function waited(): string {
  const ms = WaitActions.elementTimeout();
  return ` (waited ${ms % 1000 === 0 ? ms / 1000 : ms / 1000} s).`;
}

/** What the browser says of a field: '' when it would not send the field's form as it is, else why it would. */
function whyItWouldSend(e: HTMLInputElement): string {
  if (!e.validity) return 'it is not a field';
  if (e.value !== '') return `it held ${JSON.stringify(e.value)}`;
  if (!e.required) return 'it is not required';
  if (e.form?.noValidate) return 'its form has novalidate';
  return e.validity.valueMissing ? '' : 'the browser would send it';
}
